def tr_upper(s): return s.replace("i","İ").replace("ı","I").upper()
def translate(en):
    if en not in D: return None
    v=D[en]
    letters=[c for c in en if c.isalpha()]
    if letters and all(c.isupper() for c in letters): v=tr_upper(v)
    # keep first/last whitespace of the source
    lead=en[:len(en)-len(en.lstrip())]; trail=en[len(en.rstrip()):]
    return lead+v.strip()+trail if v.strip()==v else lead+v+trail
